namespace ScanBack.Web.Services;

public sealed partial class UiText
{
    private static readonly Dictionary<string, string> Greek = new(StringComparer.Ordinal)
    {
        ["Confirm your email"] = "Επιβεβαιώστε το email σας",
        ["Confirm this email address for your ScanBack account. You can sign in after confirming."] = "Επιβεβαιώστε αυτήν τη διεύθυνση email για τον λογαριασμό ScanBack σας. Μετά την επιβεβαίωση μπορείτε να συνδεθείτε.",
        ["Confirm email address"] = "Επιβεβαίωση διεύθυνσης email",
        ["The privacy notice changed. Review the current notice before creating your account."] = "Η ενημέρωση απορρήτου άλλαξε. Ελέγξτε την τρέχουσα ενημέρωση πριν δημιουργήσετε τον λογαριασμό σας.",
        ["Data controller and privacy contact"] = "Υπεύθυνος επεξεργασίας και επικοινωνία για το απόρρητο",
        ["{0} operates this ScanBack service. Contact"] = "Ο φορέας {0} λειτουργεί αυτήν την υπηρεσία ScanBack. Επικοινωνήστε στη διεύθυνση",
        ["about your personal data, a correction, a privacy concern or a rights request. Notice version:"] = "για τα προσωπικά δεδομένα σας, διορθώσεις, ζητήματα απορρήτου ή άσκηση δικαιωμάτων. Έκδοση ενημέρωσης:",
        ["We process account and ordinary profile details to provide the service you request under GDPR Article 6(1)(b). Optional health information, including information you choose to make public, is processed on your explicit consent under Articles 6(1)(a) and 9(2)(a). Security controls, limited administrative audit records and abuse prevention serve the legitimate interests of protecting the service and its users under Article 6(1)(f); you may ask the controller about this assessment and object to that processing. We do not sell personal data or use health information for advertising or automated decisions."] = "Επεξεργαζόμαστε τα στοιχεία λογαριασμού και τα συνήθη στοιχεία προφίλ για την παροχή της υπηρεσίας που ζητάτε, βάσει του άρθρου 6 παρ. 1 στοιχ. β του ΓΚΠΔ. Οι προαιρετικές πληροφορίες υγείας, συμπεριλαμβανομένων όσων επιλέγετε να δημοσιεύσετε, υποβάλλονται σε επεξεργασία με τη ρητή συγκατάθεσή σας, βάσει των άρθρων 6 παρ. 1 στοιχ. α και 9 παρ. 2 στοιχ. α. Οι έλεγχοι ασφαλείας, τα περιορισμένα αρχεία διοικητικών ενεργειών και η πρόληψη κατάχρησης εξυπηρετούν το έννομο συμφέρον προστασίας της υπηρεσίας και των χρηστών της, βάσει του άρθρου 6 παρ. 1 στοιχ. στ. Μπορείτε να ζητήσετε από τον υπεύθυνο επεξεργασίας πληροφορίες για αυτήν την αξιολόγηση και να αντιταχθείτε στην επεξεργασία. Δεν πωλούμε προσωπικά δεδομένα ούτε χρησιμοποιούμε πληροφορίες υγείας για διαφήμιση ή αυτοματοποιημένες αποφάσεις.",
        ["Publishing a health field deliberately discloses special-category health data to people who have your sticker link, including strangers. They can copy what they see. Withdrawing consent stops future display and deletes the stored health fields; it cannot retrieve copies someone has already made. Only publish information you intend to make available in this way."] = "Η δημοσίευση ενός πεδίου υγείας κοινοποιεί σκόπιμα δεδομένα υγείας ειδικής κατηγορίας σε άτομα που έχουν τον σύνδεσμο του αυτοκόλλητού σας, ακόμη και σε αγνώστους. Μπορούν να αντιγράψουν όσα βλέπουν. Η ανάκληση συγκατάθεσης σταματά τη μελλοντική προβολή και διαγράφει τα αποθηκευμένα πεδία υγείας· δεν μπορεί να ανακτήσει αντίγραφα που έχει ήδη δημιουργήσει κάποιος. Δημοσιεύετε μόνο πληροφορίες που επιθυμείτε να είναι διαθέσιμες με αυτόν τον τρόπο.",
        ["You may provide contact details for someone who can help in an emergency. Ask them first and provide current details. A verification message lets the recipient choose whether to participate. Notifications require recipient confirmation; public display of their telephone number requires their separate, explicit permission. Contact email addresses are never published. Recipients can decline or withdraw using the link in their invitation. Removing a contact or withdrawing their participation revokes their incident invitations."] = "Μπορείτε να καταχωρίσετε στοιχεία επικοινωνίας κάποιου που μπορεί να βοηθήσει σε έκτακτη ανάγκη. Ρωτήστε τον πρώτα και δώστε ενημερωμένα στοιχεία. Ένα μήνυμα επιβεβαίωσης επιτρέπει στον παραλήπτη να επιλέξει αν θα συμμετέχει. Οι ειδοποιήσεις απαιτούν επιβεβαίωση του παραλήπτη· η δημόσια προβολή του τηλεφώνου του απαιτεί χωριστή, ρητή άδειά του. Οι διευθύνσεις email των επαφών δεν δημοσιεύονται ποτέ. Οι παραλήπτες μπορούν να αρνηθούν ή να ανακαλέσουν τη συμμετοχή από τον σύνδεσμο της πρόσκλησης. Η αφαίρεση επαφής ή η ανάκληση συμμετοχής ανακαλεί τις προσκλήσεις της για περιστατικά.",
        ["Reports may contain the location, reporter-supplied description, consciousness status and number of people involved. They are shared only through the incident access granted to the reporter and participating emergency contacts. Do not include unnecessary sensitive information about other people."] = "Οι αναφορές μπορεί να περιέχουν τοποθεσία, περιγραφή του ατόμου που υποβάλλει την αναφορά, κατάσταση συνείδησης και αριθμό εμπλεκομένων. Κοινοποιούνται μόνο μέσω της πρόσβασης στο περιστατικό που δίνεται στο άτομο που το ανέφερε και στις συμμετέχουσες επαφές έκτακτης ανάγκης. Μην περιλαμβάνετε περιττές ευαίσθητες πληροφορίες για άλλα άτομα.",
        ["Participating contacts can receive an email invitation to an incident. Emails contain an invitation and a general alert, without the rider's medical information or precise location. An invitation is exchanged once for a secure browser cookie scoped to that incident. Access expires after {0} hours by default and may be revoked sooner. Do not forward invitations. Queued or mail-server-accepted status does not prove a person read a message."] = "Οι συμμετέχουσες επαφές μπορούν να λάβουν πρόσκληση email για ένα περιστατικό. Τα email περιέχουν πρόσκληση και γενική ειδοποίηση, χωρίς ιατρικές πληροφορίες του αναβάτη ή ακριβή τοποθεσία. Η πρόσκληση ανταλλάσσεται μία φορά με ασφαλές cookie προγράμματος περιήγησης για το συγκεκριμένο περιστατικό. Η πρόσβαση λήγει συνήθως μετά από {0} ώρες και μπορεί να ανακληθεί νωρίτερα. Μην προωθείτε προσκλήσεις. Η κατάσταση αναμονής ή αποδοχής από τον διακομιστή email δεν αποδεικνύει ότι κάποιος διάβασε το μήνυμα.",
        ["Incidents and associated invitations are removed after the current {0}-day retention period, once their access has expired. Older notification and audit records are also removed by scheduled cleanup. Cleanup runs periodically, so expiry blocks access before physical deletion completes. Settings changes can alter these periods for retained records."] = "Τα περιστατικά και οι σχετικές προσκλήσεις αφαιρούνται μετά την τρέχουσα περίοδο διατήρησης των {0} ημερών, εφόσον έχει λήξει η πρόσβασή τους. Παλαιότερες ειδοποιήσεις και αρχεία ενεργειών αφαιρούνται επίσης με προγραμματισμένο καθαρισμό. Ο καθαρισμός εκτελείται περιοδικά, επομένως η λήξη εμποδίζει την πρόσβαση πριν ολοκληρωθεί η φυσική διαγραφή. Οι αλλαγές ρυθμίσεων μπορούν να μεταβάλουν αυτές τις περιόδους για τις διατηρούμενες εγγραφές.",
        ["Your account and profile remain while your account is open. You can edit your data, change visibility, remove contacts, revoke or replace stickers, download your data and delete your account in your profile. Withdrawing health consent immediately deletes health fields and clears their public visibility. Consent withdrawal does not affect processing that was lawful before withdrawal. Account deletion removes active account data and unlinks retained audit events; separate backup copies expire under the operator's backup policy. Contact the controller for backup-retention details."] = "Ο λογαριασμός και το προφίλ σας διατηρούνται όσο ο λογαριασμός σας παραμένει ανοικτός. Από το προφίλ μπορείτε να επεξεργάζεστε δεδομένα, να αλλάζετε τη δημόσια προβολή, να αφαιρείτε επαφές, να ανακαλείτε ή να αντικαθιστάτε αυτοκόλλητα, να κατεβάζετε τα δεδομένα σας και να διαγράφετε τον λογαριασμό σας. Η ανάκληση συγκατάθεσης υγείας διαγράφει αμέσως τα πεδία υγείας και καταργεί τη δημόσια προβολή τους. Η ανάκληση δεν επηρεάζει την επεξεργασία που ήταν νόμιμη πριν από αυτήν. Η διαγραφή λογαριασμού αφαιρεί τα ενεργά δεδομένα και αποσυνδέει τις διατηρούμενες εγγραφές ενεργειών. Τα χωριστά αντίγραφα ασφαλείας λήγουν σύμφωνα με την πολιτική αντιγράφων του υπευθύνου λειτουργίας. Ζητήστε από τον υπεύθυνο επεξεργασίας λεπτομέρειες διατήρησης αντιγράφων.",
        ["Your rights"] = "Τα δικαιώματά σας",
        ["You can request access, correction, erasure, restriction or a portable copy of your data, and object to processing based on legitimate interests. Where processing relies on consent, you can withdraw it at any time. Contact {0} if self-service controls do not meet your request, including when you are an emergency contact without an account. We may need proportionate identity verification to avoid disclosing data to another person. We respond without undue delay, normally within one month; a complex request may allow an extension of up to two additional months, with an explanation within the first month. You may complain to the supervisory authority in your country of residence, work or the alleged infringement."] = "Μπορείτε να ζητήσετε πρόσβαση, διόρθωση, διαγραφή, περιορισμό ή φορητό αντίγραφο των δεδομένων σας και να αντιταχθείτε σε επεξεργασία που βασίζεται σε έννομα συμφέροντα. Όταν η επεξεργασία βασίζεται σε συγκατάθεση, μπορείτε να την ανακαλέσετε οποτεδήποτε. Επικοινωνήστε στο {0} αν οι λειτουργίες αυτοεξυπηρέτησης δεν καλύπτουν το αίτημά σας, ακόμη και αν είστε επαφή έκτακτης ανάγκης χωρίς λογαριασμό. Ενδέχεται να χρειαστεί αναλογική επαλήθευση ταυτότητας ώστε να μη δοθούν δεδομένα σε άλλο άτομο. Απαντούμε χωρίς αδικαιολόγητη καθυστέρηση, συνήθως εντός ενός μηνός. Για σύνθετο αίτημα μπορεί να επιτρέπεται παράταση έως δύο επιπλέον μηνών, με ενημέρωση εντός του πρώτου μήνα. Μπορείτε να υποβάλετε καταγγελία στην εποπτική αρχή της χώρας κατοικίας, εργασίας ή της φερόμενης παράβασης.",
        ["Account pages require authentication and ownership checks. Administrators manage account status, settings and limited incident metadata through an interface that does not display medical profiles. Profile health fields and queued email bodies are protected in the database. Necessary hosting and mail providers process data to run the service; contact the controller for the current providers, processing locations, international transfers and applicable safeguards. People with legitimate operational access may need to investigate service or security incidents."] = "Οι σελίδες λογαριασμού απαιτούν έλεγχο ταυτότητας και κυριότητας. Οι διαχειριστές ελέγχουν κατάσταση λογαριασμών, ρυθμίσεις και περιορισμένα μεταδεδομένα περιστατικών μέσω περιβάλλοντος που δεν εμφανίζει ιατρικά προφίλ. Τα πεδία υγείας προφίλ και τα σώματα email σε αναμονή προστατεύονται στη βάση δεδομένων. Οι αναγκαίοι πάροχοι φιλοξενίας και email επεξεργάζονται δεδομένα για τη λειτουργία της υπηρεσίας. Ζητήστε από τον υπεύθυνο επεξεργασίας πληροφορίες για τους τρέχοντες παρόχους, τις τοποθεσίες επεξεργασίας, τις διεθνείς διαβιβάσεις και τις ισχύουσες εγγυήσεις. Άτομα με νόμιμη επιχειρησιακή πρόσβαση ενδέχεται να χρειαστεί να ερευνήσουν λειτουργικά περιστατικά ή περιστατικά ασφαλείας.",
        ["The application uses necessary authentication, incident-access, request-security and language-preference cookies. Assets are hosted locally and the application includes no advertising or analytics trackers. Email uses the operator's configured mail service. Opening a map link or initiating a telephone call invokes the provider or device you choose. The service does not continuously track your location or send your data to an AI service."] = "Η εφαρμογή χρησιμοποιεί απαραίτητα cookie για έλεγχο ταυτότητας, πρόσβαση σε περιστατικά, ασφάλεια αιτημάτων και προτίμηση γλώσσας. Οι πόροι φιλοξενούνται τοπικά και η εφαρμογή δεν περιλαμβάνει εργαλεία διαφημιστικής παρακολούθησης ή αναλυτικών μετρήσεων. Το email χρησιμοποιεί την υπηρεσία που έχει ρυθμίσει ο υπεύθυνος λειτουργίας. Το άνοιγμα χάρτη ή η έναρξη τηλεφωνικής κλήσης χρησιμοποιεί τον πάροχο ή τη συσκευή που επιλέγετε. Η υπηρεσία δεν παρακολουθεί συνεχώς την τοποθεσία σας ούτε αποστέλλει τα δεδομένα σας σε υπηρεσία τεχνητής νοημοσύνης.",
        ["Choose each permission separately. Leaving a box unchecked declines that permission."] = "Επιλέξτε κάθε άδεια χωριστά. Αν αφήσετε ένα πλαίσιο μη επιλεγμένο, δεν δίνετε τη συγκεκριμένη άδεια.",
        ["I agree to receive emails when someone reports a possible accident for this rider. Reports are unverified and ScanBack does not contact emergency services."] = "Συμφωνώ να λαμβάνω email όταν κάποιος αναφέρει πιθανό ατύχημα για αυτόν τον αναβάτη. Οι αναφορές δεν έχουν επαληθευτεί και το ScanBack δεν επικοινωνεί με τις υπηρεσίες έκτακτης ανάγκης.",
        ["Requested public contact details"] = "Στοιχεία επαφής για τα οποία ζητείται δημόσια προβολή",
        ["I explicitly agree to publish this phone number, my name and relationship on this rider's emergency page. Anyone who scans, photographs, or receives the sticker link may see and call this number."] = "Συμφωνώ ρητά να δημοσιευτούν αυτός ο αριθμός τηλεφώνου, το όνομά μου και η σχέση μου με τον αναβάτη στη σελίδα έκτακτης ανάγκης του. Όποιος σαρώσει, φωτογραφίσει ή λάβει τον σύνδεσμο του αυτοκόλλητου μπορεί να δει και να καλέσει αυτόν τον αριθμό.",
        ["You can withdraw both permissions using the unsubscribe link in the invitation email. Changing the phone number requires new permission before it is shown."] = "Μπορείτε να ανακαλέσετε και τις δύο άδειες από τον σύνδεσμο διακοπής συμμετοχής στο email πρόσκλησης. Αν αλλάξει ο αριθμός τηλεφώνου, απαιτείται νέα άδεια πριν εμφανιστεί δημόσια.",
        ["Confirm my email and save my choices"] = "Επιβεβαίωση email και αποθήκευση επιλογών",
        ["Ask this contact for permission to publish their phone number on my public emergency page."] = "Να ζητηθεί από αυτήν την επαφή άδεια δημοσίευσης του τηλεφώνου της στη δημόσια σελίδα έκτακτης ανάγκης μου.",
        ["The contact must explicitly accept publication in their email invitation. Notification consent is separate. Changing the number removes publication until they consent again. Email addresses are never shown."] = "Η επαφή πρέπει να αποδεχτεί ρητά τη δημοσίευση μέσω της πρόσκλησης email. Η συγκατάθεση για ειδοποιήσεις είναι χωριστή. Αν αλλάξει ο αριθμός, παύει η δημοσίευσή του μέχρι να δοθεί νέα συγκατάθεση. Οι διευθύνσεις email δεν εμφανίζονται ποτέ δημόσια.",
        ["Contact added. Email notifications and public phone publication require the recipient's separate confirmation."] = "Η επαφή προστέθηκε. Οι ειδοποιήσεις email και η δημόσια προβολή τηλεφώνου απαιτούν χωριστή επιβεβαίωση από τον παραλήπτη.",
        ["Your chosen emergency contact permissions are confirmed. Published phone numbers can be seen by anyone with the rider's sticker link. Reporting does not notify emergency services."] = "Οι επιλεγμένες άδειες συμμετοχής επιβεβαιώθηκαν. Όποιος έχει τον σύνδεσμο του αυτοκόλλητου του αναβάτη μπορεί να δει τα δημοσιευμένα τηλέφωνα. Η υποβολή αναφοράς δεν ειδοποιεί τις υπηρεσίες έκτακτης ανάγκης.",
        ["This sticker was blocked by an administrator. Create a new sticker or contact support."] = "Αυτό το αυτοκόλλητο αποκλείστηκε από διαχειριστή. Δημιουργήστε νέο αυτοκόλλητο ή επικοινωνήστε με την υποστήριξη.",
        ["The privacy notice changed. Review the current permissions and confirm your choices again."] = "Η ενημέρωση απορρήτου άλλαξε. Ελέγξτε τις τρέχουσες άδειες και επιβεβαιώστε ξανά τις επιλογές σας.",
        ["The privacy notice changed. Review the current notice and confirm your health-data choice again."] = "Η ενημέρωση απορρήτου άλλαξε. Ελέγξτε την τρέχουσα ενημέρωση και επιβεβαιώστε ξανά την επιλογή σας για τα δεδομένα υγείας.",
        ["I explicitly consent to ScanBack storing my health information for emergency identification. Only the fields I select will be publicly accessible to anyone who scans, photographs, or receives my sticker URL. I can withdraw consent and delete this information at any time."] = "Συγκατατίθεμαι ρητά στην αποθήκευση των πληροφοριών υγείας μου από το ScanBack για αναγνώριση σε έκτακτη ανάγκη. Μόνο τα πεδία που επιλέγω θα είναι δημόσια προσβάσιμα σε όποιον σαρώσει, φωτογραφίσει ή λάβει τον σύνδεσμο του αυτοκόλλητού μου. Μπορώ να ανακαλέσω τη συγκατάθεση και να διαγράψω αυτές τις πληροφορίες οποτεδήποτε.",
        ["112 / 166 quick access"] = "Άμεση κλήση 112 / 166",
        ["A QR or NFC sticker contains a random URL, not medical information. Anyone with that URL, including someone who photographs your sticker, can view the fields you choose to publish. Medical fields are private by default. The profile preview lets you check the shared information. Deactivating or replacing the sticker stops future access through that identifier."] = "Ένα αυτοκόλλητο QR ή NFC περιέχει έναν τυχαίο σύνδεσμο και όχι ιατρικές πληροφορίες. Όποιος έχει αυτόν τον σύνδεσμο, ακόμη και αν φωτογραφίσει το αυτοκόλλητο, μπορεί να δει τα στοιχεία που επιλέγετε να δημοσιοποιήσετε. Τα ιατρικά πεδία είναι ιδιωτικά από προεπιλογή. Η προεπισκόπηση προφίλ σάς επιτρέπει να ελέγξετε τις κοινοποιημένες πληροφορίες. Η απενεργοποίηση ή αντικατάσταση του αυτοκόλλητου σταματά τη μελλοντική πρόσβαση μέσω αυτού του αναγνωριστικού.",
        ["A SMALL STICKER. A BIG CONNECTION."] = "ΕΝΑ ΜΙΚΡΟ ΑΥΤΟΚΟΛΛΗΤΟ. ΜΙΑ ΣΗΜΑΝΤΙΚΗ ΣΥΝΔΕΣΗ.",
        ["A few minutes of preparation can help someone reach the right information and the right people."] = "Λίγα λεπτά προετοιμασίας μπορούν να βοηθήσουν κάποιον να βρει τις σωστές πληροφορίες και τους κατάλληλους ανθρώπους.",
        ["A helmet sticker connects to an emergency profile"] = "Ένα αυτοκόλλητο στο κράνος οδηγεί στο προφίλ έκτακτης ανάγκης",
        ["A little preparation. A stronger safety net."] = "Λίγη προετοιμασία. Περισσότερη ασφάλεια.",
        ["A new contact verification email has been queued."] = "Ένα νέο email επιβεβαίωσης επαφής μπήκε σε αναμονή αποστολής.",
        ["A possible accident was recently reported for this sticker. New contact notifications are temporarily paused. Call emergency services if help is needed."] = "Αναφέρθηκε πρόσφατα πιθανό ατύχημα για αυτό το αυτοκόλλητο. Οι νέες ειδοποιήσεις επαφών έχουν προσωρινά διακοπεί. Καλέστε τις υπηρεσίες έκτακτης ανάγκης αν χρειάζεται βοήθεια.",
        ["A possible accident was reported"] = "Αναφέρθηκε πιθανό ατύχημα",
        ["A rider can have up to 10 emergency contacts."] = "Ένας αναβάτης μπορεί να έχει έως 10 επαφές έκτακτης ανάγκης.",
        ["A scan opens your emergency page. A helper can call emergency services and report a possible accident to your contacts."] = "Η σάρωση ανοίγει τη σελίδα έκτακτης ανάγκης σας. Το άτομο που σας βοηθά μπορεί να καλέσει τις υπηρεσίες έκτακτης ανάγκης και να ειδοποιήσει τις επαφές σας για πιθανό ατύχημα.",
        ["A sticker scan shows only the fields you publish. Medical information is rider supplied."] = "Η σάρωση του αυτοκόλλητου εμφανίζει μόνο τα στοιχεία που δημοσιοποιείτε. Οι ιατρικές πληροφορίες έχουν δηλωθεί από τον αναβάτη.",
        ["A trusted person"] = "Ένα άτομο εμπιστοσύνης",
        ["A verification message was recently queued. Please wait five minutes before sending another."] = "Ένα μήνυμα επιβεβαίωσης μπήκε πρόσφατα σε αναμονή αποστολής. Περιμένετε πέντε λεπτά πριν στείλετε άλλο.",
        ["ALLERGIES"] = "ΑΛΛΕΡΓΙΕΣ",
        ["Accepted by email provider"] = "Έγινε αποδεκτό από τον πάροχο email",
        ["Access expires"] = "Η πρόσβαση λήγει",
        ["Accident location"] = "Τοποθεσία ατυχήματος",
        ["Accident reports and location"] = "Αναφορές ατυχημάτων και τοποθεσία",
        ["Account"] = "Λογαριασμός",
        ["Account ID"] = "Αναγνωριστικό λογαριασμού",
        ["Account access and email verification status"] = "Πρόσβαση λογαριασμού και κατάσταση επιβεβαίωσης email",
        ["Account activated."] = "Ο λογαριασμός ενεργοποιήθηκε.",
        ["Account and administration pages require authentication and authorization. Public identifiers use random tokens. Administrators manage account status and limited incident metadata; the normal administration interface does not display medical profiles. Production operation requires HTTPS, protected encryption keys, encrypted database storage and backups, and restricted operator access. Sensitive operations are audited without placing medical contents in logs."] = "Οι σελίδες λογαριασμού και διαχείρισης απαιτούν έλεγχο ταυτότητας και εξουσιοδότηση. Τα δημόσια αναγνωριστικά χρησιμοποιούν τυχαία διακριτικά. Οι διαχειριστές ελέγχουν την κατάσταση λογαριασμών και περιορισμένα στοιχεία περιστατικών· το συνηθισμένο περιβάλλον διαχείρισης δεν εμφανίζει ιατρικά προφίλ. Η λειτουργία σε παραγωγή απαιτεί HTTPS, προστατευμένα κλειδιά κρυπτογράφησης, κρυπτογραφημένη αποθήκευση βάσης δεδομένων και αντιγράφων ασφαλείας, καθώς και περιορισμένη πρόσβαση χειριστών. Οι ευαίσθητες ενέργειες καταγράφονται χωρίς να περιλαμβάνεται ιατρικό περιεχόμενο στα αρχεία καταγραφής.",
        ["Account controls and operational health, with medical information kept private."] = "Έλεγχος λογαριασμών και λειτουργίας της πλατφόρμας, με τις ιατρικές πληροφορίες να παραμένουν ιδιωτικές.",
