        ["Rider navigation"] = "Πλοήγηση αναβάτη",
        ["Rider profile photo"] = "Φωτογραφία προφίλ αναβάτη",
        ["Rider-supplied emergency information:"] = "Πληροφορίες έκτακτης ανάγκης που έχει δηλώσει ο αναβάτης:",
        ["Role"] = "Ρόλος",
        ["SCANBACK EMERGENCY"] = "SCANBACK ΕΚΤΑΚΤΗ ΑΝΑΓΚΗ",
        ["SIMPLE BY DESIGN"] = "ΑΠΛΟ ΑΠΟ ΤΟΝ ΣΧΕΔΙΑΣΜΟ ΤΟΥ",
        ["Save contact"] = "Αποθήκευση επαφής",
        ["Save profile"] = "Αποθήκευση προφίλ",
        ["Save settings"] = "Αποθήκευση ρυθμίσεων",
        ["Save your recovery codes"] = "Αποθηκεύστε τους κωδικούς ανάκτησης",
        ["Scan for emergency information"] = "Σαρώστε για πληροφορίες έκτακτης ανάγκης",
        ["Scan this code with Microsoft Authenticator, Google Authenticator, or another TOTP app."] = "Σαρώστε αυτόν τον κωδικό με το Microsoft Authenticator, το Google Authenticator ή άλλη εφαρμογή TOTP.",
        ["Scan. Connect. Help."] = "Σαρώστε. Συνδεθείτε. Βοηθήστε.",
        ["ScanBack does not supply or program physical NFC hardware. Test printed QR codes at their final size and follow helmet manufacturer guidance before attaching a sticker."] = "Το ScanBack δεν προμηθεύει ούτε προγραμματίζει φυσικές ετικέτες NFC. Δοκιμάστε τους εκτυπωμένους κωδικούς QR στο τελικό μέγεθος και ακολουθήστε τις οδηγίες του κατασκευαστή του κράνους πριν τοποθετήσετε αυτοκόλλητο.",
        ["ScanBack helps people contact your emergency contacts. It does not call emergency services automatically."] = "Το ScanBack βοηθά στην επικοινωνία με τις επαφές έκτακτης ανάγκης σας. Δεν καλεί αυτόματα τις υπηρεσίες έκτακτης ανάγκης.",
        ["Search"] = "Αναζήτηση",
        ["Search by email or account ID"] = "Αναζήτηση με email ή αναγνωριστικό λογαριασμού",
        ["Search by sticker label or account ID"] = "Αναζήτηση με ονομασία αυτοκόλλητου ή αναγνωριστικό λογαριασμού",
        ["See how it works"] = "Δείτε πώς λειτουργεί",
        ["Select a known blood type or leave it unknown."] = "Επιλέξτε την ομάδα αίματος που γνωρίζετε ή αφήστε τη ως άγνωστη.",
        ["Self-deactivation is blocked"] = "Δεν επιτρέπεται η απενεργοποίηση του δικού σας λογαριασμού",
        ["Send email"] = "Αποστολή email",
        ["Set a new password"] = "Ορίστε νέο κωδικό πρόσβασης",
        ["Set up two-factor authentication"] = "Ρύθμιση ελέγχου ταυτότητας δύο παραγόντων",
        ["Share my current location"] = "Κοινοποίηση τρέχουσας τοποθεσίας μου",
        ["Share this phone's location only if you are at the accident. Your browser will ask for permission. You can report without GPS."] = "Κοινοποιήστε την τοποθεσία αυτού του τηλεφώνου μόνο αν βρίσκεστε στο σημείο του ατυχήματος. Ο περιηγητής σας θα ζητήσει άδεια. Μπορείτε να υποβάλετε αναφορά χωρίς GPS.",
        ["Share what helps."] = "Μοιραστείτε όσα βοηθούν.",
        ["Shared emergency information"] = "Κοινοποιημένες πληροφορίες έκτακτης ανάγκης",
        ["Shared information only"] = "Μόνο κοινοποιημένες πληροφορίες",
        ["Shared location removed. You can submit without GPS."] = "Η κοινοποιημένη τοποθεσία αφαιρέθηκε. Μπορείτε να υποβάλετε την αναφορά χωρίς GPS.",
        ["Showing the 100 most recent audit events."] = "Εμφανίζονται οι 100 πιο πρόσφατες καταγεγραμμένες ενέργειες.",
        ["Showing the 100 most recent incidents."] = "Εμφανίζονται τα 100 πιο πρόσφατα περιστατικά.",
        ["Showing up to 100 accounts. Refine your search to find a specific account."] = "Εμφανίζονται έως 100 λογαριασμοί. Περιορίστε την αναζήτηση για να βρείτε συγκεκριμένο λογαριασμό.",
        ["Showing up to 100 identifiers. Revocation is permanent; the rider can create a replacement."] = "Εμφανίζονται έως 100 αναγνωριστικά. Η ανάκληση είναι οριστική· ο αναβάτης μπορεί να δημιουργήσει αντικατάσταση.",
        ["Sign in"] = "Σύνδεση",
        ["Sign in to your rider dashboard."] = "Συνδεθείτε στον πίνακα ελέγχου αναβάτη σας.",
        ["Six-digit authenticator code"] = "Εξαψήφιος κωδικός εφαρμογής ελέγχου ταυτότητας",
        ["Skip to content"] = "Μετάβαση στο περιεχόμενο",
        ["Something went wrong"] = "Παρουσιάστηκε πρόβλημα",
        ["Start with a profile. Keep it ready for the road."] = "Ξεκινήστε με ένα προφίλ. Διατηρήστε το έτοιμο για τον δρόμο.",
        ["Status"] = "Κατάσταση",
        ["Sticker"] = "Αυτοκόλλητο",
        ["Sticker activated."] = "Το αυτοκόλλητο ενεργοποιήθηκε.",
        ["Sticker deactivated. Its emergency page and existing incident links are unavailable."] = "Το αυτοκόλλητο απενεργοποιήθηκε. Η σελίδα έκτακτης ανάγκης του και οι υπάρχοντες σύνδεσμοι περιστατικών δεν είναι διαθέσιμοι.",
        ["Sticker label"] = "Ονομασία αυτοκόλλητου",
        ["Sticker replaced. The previous QR code, NFC URL, and incident links are invalid. Print the new QR code and reprogram the NFC sticker."] = "Το αυτοκόλλητο αντικαταστάθηκε. Ο προηγούμενος κωδικός QR, ο σύνδεσμος NFC και οι σύνδεσμοι περιστατικών είναι άκυροι. Εκτυπώστε τον νέο κωδικό QR και γράψτε τον νέο σύνδεσμο στο αυτοκόλλητο NFC.",
        ["Stop emergency notifications"] = "Διακοπή ειδοποιήσεων έκτακτης ανάγκης",
        ["Stop notifications and public phone sharing"] = "Διακοπή ειδοποιήσεων και δημόσιας προβολής τηλεφώνου",
        ["Stop notifications for"] = "Διακοπή ειδοποιήσεων για",
        ["Street, junction, direction of travel, or a nearby landmark"] = "Οδός, διασταύρωση, κατεύθυνση πορείας ή κοντινό σημείο αναφοράς",
        ["Submit once. A restricted incident page will open with notification status and a communication guide."] = "Υποβάλετε την αναφορά μία φορά. Θα ανοίξει μια σελίδα περιστατικού περιορισμένης πρόσβασης με την κατάσταση ειδοποιήσεων και έναν οδηγό επικοινωνίας.",
        ["THE NEXT RIDE STARTS HERE"] = "Η ΕΠΟΜΕΝΗ ΔΙΑΔΡΟΜΗ ΞΕΚΙΝΑ ΕΔΩ",
        ["Technical audit metadata"] = "Τεχνικά στοιχεία καταγραφής ενεργειών",
        ["Tell your contact why you are adding them and ask permission before publishing their phone number."] = "Εξηγήστε στην επαφή σας γιατί την προσθέτετε και ζητήστε άδεια πριν δημοσιοποιήσετε τον αριθμό τηλεφώνου της.",
        ["The QR code and this NFC URL open the same emergency page."] = "Ο κωδικός QR και αυτός ο σύνδεσμος NFC ανοίγουν την ίδια σελίδα έκτακτης ανάγκης.",
        ["The account could not be updated. Try again."] = "Δεν ήταν δυνατή η ενημέρωση του λογαριασμού. Δοκιμάστε ξανά.",
        ["The application uses necessary authentication, request-security and language-preference cookies. Its interface assets are hosted locally, with no advertising or analytics trackers included. Email uses the operator's configured mail service. Opening a map link or initiating a telephone call invokes the service or device you choose. Continuous location tracking and an external AI service are not part of this MVP."] = "Η εφαρμογή χρησιμοποιεί απαραίτητα cookies για έλεγχο ταυτότητας, ασφάλεια αιτημάτων και επιλογή γλώσσας. Τα αρχεία του περιβάλλοντος χρήστη φιλοξενούνται τοπικά, χωρίς μηχανισμούς παρακολούθησης διαφημίσεων ή ανάλυσης επισκεψιμότητας. Το email χρησιμοποιεί την υπηρεσία αποστολής που έχει ρυθμίσει ο υπεύθυνος λειτουργίας. Το άνοιγμα συνδέσμου χάρτη ή η έναρξη τηλεφωνικής κλήσης ενεργοποιεί την υπηρεσία ή συσκευή που επιλέγετε. Η συνεχής παρακολούθηση τοποθεσίας και η εξωτερική υπηρεσία τεχνητής νοημοσύνης δεν περιλαμβάνονται σε αυτό το MVP.",
        ["The authenticator code is invalid. Please try again."] = "Ο κωδικός της εφαρμογής ελέγχου ταυτότητας δεν είναι έγκυρος. Δοκιμάστε ξανά.",
        ["The bystander reports that the rider appears conscious."] = "Το άτομο που βοηθά αναφέρει ότι ο αναβάτης φαίνεται να έχει τις αισθήσεις του.",
        ["The bystander reports that the rider appears unconscious."] = "Το άτομο που βοηθά αναφέρει ότι ο αναβάτης φαίνεται να μην έχει τις αισθήσεις του.",
        ["The exact location is not available; describe landmarks to the dispatcher."] = "Η ακριβής τοποθεσία δεν είναι διαθέσιμη· περιγράψτε σημεία αναφοράς στον τηλεφωνητή έκτακτης ανάγκης.",
        ["The last active administrator cannot be deactivated."] = "Δεν μπορεί να απενεργοποιηθεί ο τελευταίος ενεργός διαχειριστής.",
        ["The latitude is invalid."] = "Το γεωγραφικό πλάτος δεν είναι έγκυρο.",
        ["The link is invalid or expired. Request another password reset."] = "Ο σύνδεσμος είναι άκυρος ή έχει λήξει. Ζητήστε νέα επαναφορά κωδικού πρόσβασης.",
        ["The location coordinate is invalid."] = "Η συντεταγμένη τοποθεσίας δεν είναι έγκυρη.",
        ["The longitude is invalid."] = "Το γεωγραφικό μήκος δεν είναι έγκυρο.",
        ["The password is incorrect."] = "Ο κωδικός πρόσβασης είναι λανθασμένος.",
        ["The person scanning your sticker can call a published contact number. Email addresses are never shown."] = "Το άτομο που σαρώνει το αυτοκόλλητο μπορεί να καλέσει δημοσιευμένο τηλέφωνο επαφής. Τα email δεν εμφανίζονται ποτέ.",
        ["The reporting form has expired. Reload this page."] = "Η φόρμα αναφοράς έχει λήξει. Φορτώστε ξανά τη σελίδα.",
        ["The rider appears conscious"] = "Ο αναβάτης φαίνεται να έχει τις αισθήσεις του",
        ["The rider appears unconscious"] = "Ο αναβάτης φαίνεται να μην έχει τις αισθήσεις του",
        ["The rider's consciousness has not been established."] = "Δεν έχει διαπιστωθεί αν ο αναβάτης έχει τις αισθήσεις του.",
        ["The stored sticker link cannot be recovered. Replace this sticker to create a new secure link."] = "Δεν είναι δυνατή η ανάκτηση του αποθηκευμένου συνδέσμου. Αντικαταστήστε το αυτοκόλλητο για να δημιουργηθεί νέος ασφαλής σύνδεσμος.",
        ["The verification code is invalid. Try a new code or use a recovery code."] = "Ο κωδικός επαλήθευσης δεν είναι έγκυρος. Δοκιμάστε νέο κωδικό ή χρησιμοποιήστε έναν κωδικό ανάκτησης.",
        ["These buttons open your phone dialer. ScanBack does not call or dispatch emergency services."] = "Αυτά τα κουμπιά ανοίγουν την εφαρμογή κλήσεων του τηλεφώνου σας. Το ScanBack δεν καλεί ούτε αποστέλλει υπηρεσίες έκτακτης ανάγκης.",
        ["These codes are displayed once. Sign in again to continue."] = "Αυτοί οι κωδικοί εμφανίζονται μία φορά. Συνδεθείτε ξανά για να συνεχίσετε.",
        ["These screens expose account status, identifier status, delivery counts, and incident timestamps. Medical details, precise locations, contact addresses, and access tokens are excluded."] = "Αυτές οι οθόνες εμφανίζουν την κατάσταση λογαριασμών και αναγνωριστικών, πλήθος αποστολών και χρόνους περιστατικών. Δεν περιλαμβάνουν ιατρικές πληροφορίες, ακριβείς τοποθεσίες, διευθύνσεις επαφών ή διακριτικά πρόσβασης.",
        ["This account is temporarily locked. Try again later."] = "Αυτός ο λογαριασμός είναι προσωρινά κλειδωμένος. Δοκιμάστε ξανά αργότερα.",
        ["This action permanently removes your active personal data."] = "Αυτή η ενέργεια διαγράφει οριστικά τα ενεργά προσωπικά σας δεδομένα.",
        ["This address stays private and must be confirmed before emergency notifications."] = "Αυτή η διεύθυνση παραμένει ιδιωτική και πρέπει να επιβεβαιωθεί πριν από την αποστολή ειδοποιήσεων έκτακτης ανάγκης.",
        ["This confirmation link is invalid or expired."] = "Αυτός ο σύνδεσμος επιβεβαίωσης είναι άκυρος ή έχει λήξει.",
        ["This confirmation link is invalid or expired. Request another confirmation email."] = "Αυτός ο σύνδεσμος επιβεβαίωσης είναι άκυρος ή έχει λήξει. Ζητήστε νέο email επιβεβαίωσης.",
        ["This contact will be removed, pending notifications deleted, and their incident access revoked."] = "Αυτή η επαφή θα αφαιρεθεί, οι εκκρεμείς ειδοποιήσεις της θα διαγραφούν και η πρόσβασή της σε περιστατικά θα ανακληθεί.",
        ["This emergency link is unavailable or has expired."] = "Αυτός ο σύνδεσμος έκτακτης ανάγκης δεν είναι διαθέσιμος ή έχει λήξει.",
        ["This immediately deletes all health fields and removes their public visibility. Your account, identity details and stickers remain available."] = "Αυτό διαγράφει αμέσως όλα τα πεδία υγείας και καταργεί τη δημόσια προβολή τους. Ο λογαριασμός, τα στοιχεία ταυτότητας και τα αυτοκόλλητά σας παραμένουν διαθέσιμα.",
        ["This invitation is invalid, expired, or already used. Ask the rider to send a new confirmation email."] = "Αυτή η πρόσκληση είναι άκυρη, έχει λήξει ή έχει ήδη χρησιμοποιηθεί. Ζητήστε από τον αναβάτη να στείλει νέο email επιβεβαίωσης.",
        ["This is a recovery code"] = "Αυτός είναι κωδικός ανάκτησης",
        ["This is a technical privacy summary for the MVP. The operator must complete the controller details, legal bases, processor agreements and privacy notice before using the service with real riders."] = "Αυτή είναι μια τεχνική σύνοψη απορρήτου για το MVP. Ο υπεύθυνος λειτουργίας πρέπει να συμπληρώσει τα στοιχεία υπευθύνου επεξεργασίας, τις νομικές βάσεις, τις συμφωνίες με εκτελούντες την επεξεργασία και την ενημέρωση απορρήτου πριν χρησιμοποιηθεί η υπηρεσία με πραγματικούς αναβάτες.",
        ["This is one location reported by the assisting person. It is not live tracking and has not been verified."] = "Αυτή είναι μία τοποθεσία που δήλωσε το άτομο που βοηθά. Δεν αποτελεί ζωντανή παρακολούθηση και δεν έχει επαληθευτεί.",
        ["This link is invalid or the contact has been removed."] = "Αυτός ο σύνδεσμος είναι άκυρος ή η επαφή έχει αφαιρεθεί.",
        ["This report has already been submitted. Use your incident link, or reload this page."] = "Αυτή η αναφορά έχει ήδη υποβληθεί. Χρησιμοποιήστε τον σύνδεσμο περιστατικού ή φορτώστε ξανά τη σελίδα.",
        ["This report is unverified. ScanBack has not contacted emergency services."] = "Αυτή η αναφορά δεν έχει επαληθευτεί. Το ScanBack δεν έχει επικοινωνήσει με τις υπηρεσίες έκτακτης ανάγκης.",
        ["This sticker is inactive. Activate it before use."] = "Αυτό το αυτοκόλλητο είναι ανενεργό. Ενεργοποιήστε το πριν από τη χρήση.",
        ["Time"] = "Χρόνος",
        ["Try another email address or account ID."] = "Δοκιμάστε άλλη διεύθυνση email ή αναγνωριστικό λογαριασμού.",
        ["Two-factor authentication enabled"] = "Ο έλεγχος ταυτότητας δύο παραγόντων ενεργοποιήθηκε",
        ["Two-factor authentication is enabled. Store these codes somewhere safe. Each code can be used once if you lose access to your authenticator."] = "Ο έλεγχος ταυτότητας δύο παραγόντων είναι ενεργός. Φυλάξτε αυτούς τους κωδικούς σε ασφαλές μέρος. Κάθε κωδικός χρησιμοποιείται μία φορά αν χάσετε την πρόσβαση στην εφαρμογή ελέγχου ταυτότητας.",
        ["Two-factor verification"] = "Επαλήθευση δύο παραγόντων",
        ["Unable to sign in. Check your details and confirm your email address."] = "Δεν ήταν δυνατή η σύνδεση. Ελέγξτε τα στοιχεία σας και επιβεβαιώστε το email σας.",
        ["Unconfirmed"] = "Μη επιβεβαιωμένο",
        ["Understand how your data is used"] = "Δείτε πώς χρησιμοποιούνται τα δεδομένα σας",
        ["Unknown / not provided"] = "Άγνωστο / δεν έχει δηλωθεί",
        ["Upload a photo before making it public."] = "Μεταφορτώστε φωτογραφία πριν ενεργοποιήσετε τη δημόσια προβολή της.",
        ["Use a simple label that can be shown publicly, such as Helmet or Spare helmet. You can create up to 10 stickers."] = "Χρησιμοποιήστε μια απλή ονομασία που μπορεί να εμφανίζεται δημόσια, όπως Κράνος ή Εφεδρικό κράνος. Μπορείτε να δημιουργήσετε έως 10 αυτοκόλλητα.",
        ["Use at least 12 characters with uppercase, lowercase, a number and a symbol."] = "Χρησιμοποιήστε τουλάχιστον 12 χαρακτήρες με κεφαλαία, πεζά, έναν αριθμό και ένα σύμβολο.",
        ["Use this script when calling. Confirm the facts you know and follow the dispatcher's questions. This guide does not diagnose injuries."] = "Χρησιμοποιήστε αυτό το κείμενο στην κλήση σας. Επιβεβαιώστε όσα γνωρίζετε και απαντήστε στις ερωτήσεις του τηλεφωνητή έκτακτης ανάγκης. Αυτός ο οδηγός δεν κάνει διάγνωση τραυματισμών.",
        ["Use your browser's print command. Keep the white border around the QR code and test the printed sticker with your phone."] = "Χρησιμοποιήστε την εντολή εκτύπωσης του περιηγητή. Διατηρήστε το λευκό περιθώριο γύρω από τον κωδικό QR και δοκιμάστε το εκτυπωμένο αυτοκόλλητο με το κινητό σας.",
        ["Verification or recovery code"] = "Κωδικός επαλήθευσης ή ανάκτησης",
        ["Verify and sign in"] = "Επαλήθευση και σύνδεση",
        ["View all"] = "Προβολή όλων",
        ["View audit log"] = "Προβολή αρχείου ενεργειών",
        ["We could not complete this request. Please try again."] = "Δεν ήταν δυνατή η ολοκλήρωση του αιτήματος. Δοκιμάστε ξανά.",
        ["Welcome back"] = "Καλώς επιστρέψατε",
        ["What a helmet scan reveals"] = "Τι εμφανίζει η σάρωση του κράνους",
        ["What a sticker scan reveals"] = "Τι εμφανίζει η σάρωση του αυτοκόλλητου",
        ["What have you observed?"] = "Τι έχετε παρατηρήσει;",
        ["What is collected"] = "Ποια δεδομένα συλλέγονται",
